,{
"ClauseCode":"1018315"
,"ClauseContent":"<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">The insurance hereby extend to cover alterations, additions and improvements (but not appreciation in value) in excess of the sums insured for machinery specified in the Policy for an amount not exceeding 10% of the total sums insured thereby or as amount entered in the&nbsp;Schedule whichever is the less.</span></span></p>"
