,{
"ClauseCode":"1017817"
,"ClauseContent":"<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">This insurance shall be extended to cover extra charges for overtime, night work, work on public&nbsp;holidays and express freight (excluding airfreight).&nbsp;<br />\nProvided always that such extra charges shall incurred in connection with any loss of or damage to the insured items recoverable under this Policy. If the sum(s) insured of the damages item(s) is (are) less than the amount(s) required to be insured, the amount payable under this Endorsement for such extra charges shall be reduced in the same proportion</span></span></p>"
,"ClauseDescription":"Cover of Extra Charges for Overtime, Night Work, Work on Public Holidays and Express Freight (10% of Limit of Liability)"
,"ClauseTitle":"Cover for Overtime, Night work and Express Freight Clause - MR 006 (10% of Limit of Liability) [BINDER KBRU 2024]"
,"IsHeaderClause":"false"
,"KodeSection":"4"
,"pxCreateDateTime":"20251224T033734.371 GMT"
,"pxCreateOperator":"DIDIKSAPUTRA_1"
,"pxCreateOpName":"DIDIK SAPUTRA"
,"pxCreateSystemID":"pegaprodasm83"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
,"Section":"4"
}
,{
"ClauseCode":"1017818"
,"ClauseContent":"<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">It is agreed and understood that otherwise subject to the terms, exclusions, provisions and conditions contained in the Policy or endorsed thereon,<br />\nThe insurers shall indemnify the insured for loss of or damage to refractory materials and/or masonry (Exclusion 2 contained in the Policy shall be deleted as far as applicable) in item(s) No.(s) contained in the specification of the Policy, caused by an indemnifiable accident to the above-named items, subject to depreciation of the amount indemnifiable in respect of the items thus affected, at an annual rate to be determined at the time of loss, this rate being not less than 10% per annum, but, not more than 50% in total.</span></span></p>"
,"ClauseDescription":"Cover for Refractory Materials and/or Masonry in Industrial Furnace and Boilers"
,"ClauseTitle":"Cover for Refractory Materials and/or Masonry In Industrial Furnace and Boilers [BINDER KBRU 2024]"
,"IsHeaderClause":"false"
,"KodeSection":"4"
,"pxCreateDateTime":"20251224T033811.078 GMT"
,"pxCreateOperator":"DIDIKSAPUTRA_1"
,"pxCreateOpName":"DIDIK SAPUTRA"
,"pxCreateSystemID":"pegaprodasm83"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
,"Section":"4"
}
,{
"ClauseCode":"1017819"
,"ClauseContent":"<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">It is hereby declared and agreed that exclusion 2 is revised to become:<br />\nLoss of or damage to exchangeable tools, e.g. dies, moulds, engraved cylinders, parts which by their use and/or nature suffer a high rate of wear or depreciation, e.g. refractory linings, crushing hammers, objects made of glass, belts, ropes, wires, rubber tyres, operating media, e.g. lubricants, fuels, catalyst. Unless the loss or damage to such an item arises out of an accident for which the insurer is liable. The indemnification shall be limited to the actual value of such items immediately prior to the occurence of the loss or damage which is calculated by deducting proper depreciation.</span></span></p>"
,"ClauseDescription":"Cover for Replaceable Parts"
,"ClauseTitle":"Cover for Replaceable Parts [BINDER KBRU 2024]"
,"IsHeaderClause":"false"
,"KodeSection":"4"
,"pxCreateDateTime":"20251224T033821.835 GMT"
,"pxCreateOperator":"DIDIKSAPUTRA_1"
,"pxCreateOpName":"DIDIK SAPUTRA"
,"pxCreateSystemID":"pegaprodasm83"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
,"SearchClause":"Cover for Replaceable Parts"
,"Section":"4"
}
,{
"ClauseCode":"1017810"
,"ClauseContent":"<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">This insurance shall be extended to cover extra charges for airfreight.<br />\nProvided always that such extra charges are incurred in connection with any loss of or damage to the insured items recoverable under the Policy.<br />\nProvided further that the amount payable under this Endorsement in respect of airfreight shall not&nbsp;<br />\nexceed IDR 250.000.000 a.o.a and in aggregate&nbsp;during the period of insurance</span></span></p>"
,"ClauseDescription":"Cover of Extra Charges for Airfreight (Limit IDR 250,000,000.00 anyone occurrence and in aggregate)"
,"ClauseTitle":"Cover of Extra Charges for Airfreight (Limit IDR 250,000,000.00 a.o.a and in aggregate)"
,"IsHeaderClause":"false"
,"KodeSection":"1"
,"pxCreateDateTime":"20251224T033830.933 GMT"
,"pxCreateOperator":"DIDIKSAPUTRA_1"
,"pxCreateOpName":"DIDIK SAPUTRA"
,"pxCreateSystemID":"pegaprodasm83"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
,"Section":"1"
}
,{
"ClauseCode":"1012221"
,"ClauseContent":"<p align=\"JUSTIFY\" lang=\"en-US\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">It is noted and agreed that in the event of spares currently insured hereunder and represented within the total sum insured under the policy becoming obsolete following an indemnifiable loss to the unit and/or units to which they belong, such spares shall also be deemed a constructive total loss. Provided always that such spares cannot be used as spares for any other units within the premises of the insured. Insurers retain salvage rights over such spares.</span></span></p>\n\n<p align=\"JUSTIFY\" lang=\"en-US\">&nbsp;</p>"
,"ClauseDescription":"Defunct Spares Clause"
,"ClauseTitle":"Defunct Spares Clause"
,"IsHeaderClause":"false"
,"KodeSection":"4"
,"pxCreateDateTime":"20251224T033842.279 GMT"
,"pxCreateOperator":"DIDIKSAPUTRA_1"
,"pxCreateOpName":"DIDIK SAPUTRA"
,"pxCreateSystemID":"pegaprodasm83"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
,"SearchClause":"Defunct Spares Clause"
,"Section":"4"
}
,{
"ClauseCode":"1005538"
,"ClauseContent":"<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\">For the purpose of determining where necessary the item under which any property is insured, it is agreed to accept the designation under which such property has been entered in the Insured&#39;s books</span></p>"
,"ClauseDescription":"Designation Clause"
,"ClauseTitle":"Designation Clause"
,"IsHeaderClause":"false"
,"KodeSection":"1"
,"pxCreateDateTime":"20251224T033853.754 GMT"
,"pxCreateOperator":"DIDIKSAPUTRA_1"
