,"Section":"1"
}
,{
"ClauseCode":"1015718"
,"ClauseContent":"<table align=\"left\" hspace=\"0\" vspace=\"0\">\n\t<tbody>\n\t\t<tr>\n\t\t\t<td align=\"left\" valign=\"top\">\n\t\t\t<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">The insurance by this policy is extended to cover any extra cost insured in respect of express delivery airfreight, overtime Sunday and Holiday rates of wages in connection with repairs or replacements indemnifiable by this policy, the liability of the Insurers under this Endorsements shall in no case exceed the percent of the amount which the repair or replacement would have cost if these expenses had not been incurred.&nbsp; Subject otherwise to the terms exceptions, and conditions of this policy.</span></span></p>\n\n\t\t\t<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">In addition to the above, this policy also covers the reasonable and necessary costs incurred to pay for the temporary repair of insured damage to insured property and to expedite the permanent repair or replacement of such damaged property.</span></span></p>\n\t\t\t</td>\n\t\t</tr>\n\t</tbody>\n</table>"
,"ClauseDescription":"Expediting Expenses Clauses (10% of claim)"
,"ClauseTitle":"Expediting Expenses Clauses (10% of claim)"
,"IsHeaderClause":"false"
,"KodeSection":"1"
,"pxCreateDateTime":"20251224T033859.492 GMT"
,"pxCreateOperator":"DIDIKSAPUTRA_1"
,"pxCreateOpName":"DIDIK SAPUTRA"
,"pxCreateSystemID":"pegaprodasm83"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
,"SearchClause":"editing E"
,"Section":"1"
}
,{
"ClauseCode":"1012224"
,"ClauseContent":"<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">It is hereby understood and agreed that the reasonable charges raised by any&nbsp; local authority for the provision of Fire Fighting Appliances called for the purpose of protecting the premises shall be recoverable hereunder.</span></span></p>"
,"ClauseDescription":"Fire Brigades Charges Clause (Reasonable Cost)"
,"ClauseTitle":"Fire Brigades Charges Clause"
