,"SearchClause":"re Briga"
,"Section":"4"
}
,{
"ClauseCode":"1017859"
,"ClauseContent":"<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">The Insurance by this Policy extends to cover loss of or damage to the fire extinguishing appliances caused by the Insured perils.<br />\nThis extension is deemed to include the reasonable costs of refilling the fire extinguishing appliances the extinguishment of fire endangering the safety of the insured property.</span></span></p>"
,"ClauseDescription":"Fire Extinguishing Cost Clause (Reasonable Cost)"
,"ClauseTitle":"Fire Extinguishing Cost Clause [BINDER KBRU 2024]"
,"IsHeaderClause":"false"
,"KodeSection":"1"
,"pxCreateDateTime":"20251224T033914.615 GMT"
