,{
"ClauseCode":"1012231"
,"ClauseContent":"<div>\n<table align=\"left\" hspace=\"0\" vspace=\"0\">\n\t<tbody>\n\t\t<tr>\n\t\t\t<td align=\"left\" style=\"padding-top:0in; padding-right:9.0pt; padding-bottom:0in; padding-left:9.0pt\" valign=\"top\">\n\t\t\t<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">It is hereby agreed that the property insured by this Policy (other than any stock in trade or merchandise) is covered in respect of the perils hereby insured against whilst temporarily removed for cleaning, renovation, repair or other similar purposes elsewhere on the same premises or any other premises in the Republic of Indonesia and in transit thereto and therefrom by road, rail or inland waterway.</span></span></p>\n\n\t\t\t<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n\t\t\t<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">Provided always that :</span></span></p>\n\n\t\t\t<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n\t\t\t<p style=\"margin-left:23.4pt; text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">1.&nbsp;&nbsp;&nbsp;&nbsp; The amount recoverable under this extension in respect of each item of this Policy shall not exceed the amount which&nbsp; have been recoverable had the loss occurred in that part of the premises from which the property is temporary removed nor in the respect of any loss occurring elsewhere than at the said premises, for amount 10 percent of the sum insured by this Policy after deducting therefrom the value of any building (exclusive of fixtures and fittings), stock in trade or merchandise hereby insured. </span></span></p>\n\n\t\t\t<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n\t\t\t<p style=\"margin-left:23.4pt; text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">2.&nbsp;&nbsp;&nbsp;&nbsp; This extension does not apply to property if any and so far as it is otherwise insured.</span></span></p>\n\n\t\t\t<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n\t\t\t<p style=\"margin-left:.25in; text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">3.&nbsp;&nbsp; As regards losses occurring elsewhere that at the premises from which the property is temporarily removed this extension does not apply to :</span></span></p>\n\n\t\t\t<p style=\"margin-left:.25in; text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">a. motor vehicles and motor chassis licensed for normal road use</span></span></p>\n\n\t\t\t<p style=\"margin-left:.25in; text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">b. property held by the insured in trust, other than machinery and plant. other than goods on hire</span></span></p>\n\n\t\t\t<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">This clause is subject otherwise to all the terms and conditions of the Policy to which it is attached.</span></span></p>\n\t\t\t</td>\n\t\t</tr>\n\t</tbody>\n</table>\n</div>"
,"ClauseDescription":"Temporary Removal Clause"
,"ClauseTitle":"Temporary Removal Clause"
,"IsHeaderClause":"false"
