,{
"ClauseCode":"1014605"
,"ClauseContent":"<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">It is hereby noted and agreed for claim amount not exceeding IDR.100,000,000.00 due to any peril(s) covered under this policy, The Insurer(s) has automatically accepted and will pay to the Insured within 14 days from the date Insurer received the following documents:</span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">1. Signed &amp; filled claim form (with chronology and amount of claim)</span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">2. Supporting document of detail of loss (quotation details and or repair/replace invoices)</span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">3. Photos of Incident</span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">4. Police report for burglary claim</span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">5. Letter of Discharge</span></span></p>"
