,{
"ClauseCode":"1003688"
,"ClauseContent":"<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">Notwithstanding any provision to the contrary within this insurance or any endorsement thereto it is agreed that this insurance excludes loss, damage, cost or expense of whatsoever nature directly or indirectly caused by, resulting from or in connection with any act of terrorism regardless of any other cause or event contributing concurrently or in any other sequence to the loss.</span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">For the purpose of this endorsement an act of terrorism means an act, including but not limited to the use of force or violence and/or the threat thereof, of any person or group(s) of persons, whether acting alone or on behalf of or in connection with any organization(s) or government(s), committed for political, religious, ideological or similar purposes including the intention to influence any government and/or to put the public, or any section of the public, in fear.</span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">This endorsement also excludes loss, damage, cost or expense of whatsoever nature directly or indirectly caused by, resulting from or in connection with any action taken in controlling, preventing, suppressing or in any way relating to any act of terrorism.</span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">If the Underwriters allege that by reason of this exclusion, any loss, damage, cost or expense is not covered by this insurance the burden of proving the contrary shall be upon the Assured.</span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">In the event any portion of this endorsement is found to be invalid or unenforceable, the remainder shall remain in full force and effect.</span></span></p>\n\n<p align=\"JUSTIFY\" lang=\"id-ID\">&nbsp;</p>"
,"ClauseDescription":"Terrorism Exclusion Endorsement NMA 2920"
,"ClauseTitle":"Terrorism Exclusion Endorsement NMA 2920"
,"IsHeaderClause":"false"
,"KodeSection":"4"
,"pxCreateDateTime":"20251224T035018.750 GMT"
,"pxCreateOperator":"DIDIKSAPUTRA_1"
,"pxCreateOpName":"DIDIK SAPUTRA"
,"pxCreateSystemID":"pegaprodasm83"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
,"SearchClause":"errorism Exclusion End"
,"Section":"4"
}
,{
"ClauseCode":"1014610"
,"ClauseContent":"<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">All Transmission and distribution, including transmitter, piping, wire, cables, poles, pylons, standard towers and any equipment of any type of which may be attendant to such installation of any description. This exclusion includes but not limited to transmission or distribution of electrical power, telephone or telegraph signal and all communication signals whether audio or visual. This exclusion applies to both above and below ground equipment except that which is within 1,000.00 meters of the insured&rsquo;s premises or as defined in the Assured&rsquo;soriginal policy (ies). This exclusion applies both to physical or damage to the equipment and all business interruption, consequential loss and/or other contingent losses related to transmission and distribution lines.<span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\"> </span></span></p>"
,"ClauseDescription":"Transmission and Distribution Lines Exclusion Clause (1,000.00 Meters)"
,"ClauseTitle":"Transmission and Distribution Lines Exclusion Clause"
,"IsHeaderClause":"false"
,"KodeSection":"4"
