,{
"ClauseCode":"1014612"
,"ClauseContent":"<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">Any claimant under this Policy shall at the request and at the expenses of the underwriters do and concur in doing and permit to be done all such acts and things as may be necessarily or reasonably required by the Company for the purpose of endorsing any rights and remedies or of obtaining relief of Indemnity from other parties whether such acts and Company. The rights of Subrogation against association, affiliated and/or subsidiary cooperation or companies and/or any partner, office and/or individual connected therewith is hereby waived by the Insurer.</span></span></p>"
,"ClauseDescription":"Waiver of subrogation clause (against subsidiary only)"
,"ClauseTitle":"Waiver of subrogation clause (against subsidiary only)"
,"IsHeaderClause":"false"
