,{
"ClauseCode":"1017259"
,"ClauseContent":"<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">This Insurance does not cover any liability assumed by the Insured for loss or damage directly or occasioned by, happening through or in consequence of war, invasion, acts of foreign enemies, hostilities or war-like operations (whether war be declared or not), civil war, munity, civil commotion assuming the proportions of or amounting to popular rising, military rising, insurrection, rebellion, revolution, military or usurped power, martial law, confiscation or nationalisation or requisition or destruction of or damage to property by or under the order of any Government or public or local authority</span></span></p>"
,"ClauseDescription":"War and Civil War Exclusion Clause"
,"ClauseTitle":"WAR AND CIVIL WAR EXCLUSION CLAUSE NMA 464"
,"IsHeaderClause":"false"
,"KodeSection":"4"
,"pxCreateDateTime":"20251224T035059.301 GMT"
